CREATE TABLE "auth_credentials" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" bigint NOT NULL,
  "password_hash" character varying NULL,
  "must_change_password" boolean NOT NULL DEFAULT false,
  "password_changed_at" timestamptz NULL,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "auth_credentials_users_user_id"
    FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
CREATE UNIQUE INDEX "auth_credentials_user_id_key" ON "auth_credentials" ("user_id");

CREATE TABLE "auth_refresh_sessions" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" bigint NOT NULL,
  "token_id" character varying NOT NULL,
  "expires_at" timestamptz NOT NULL,
  "revoked_at" timestamptz NULL,
  "replaced_by_token_id" character varying NULL,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "auth_refresh_sessions_users_user_id"
    FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
CREATE UNIQUE INDEX "auth_refresh_sessions_token_id_key" ON "auth_refresh_sessions" ("token_id");
CREATE INDEX "auth_refresh_sessions_user_id_idx" ON "auth_refresh_sessions" ("user_id");
CREATE INDEX "auth_refresh_sessions_expires_at_idx" ON "auth_refresh_sessions" ("expires_at");

COMMENT ON TABLE "auth_credentials" IS '认证凭据表（认证模块）';
COMMENT ON COLUMN "auth_credentials"."id" IS '认证凭据主键';
COMMENT ON COLUMN "auth_credentials"."user_id" IS '关联用户资料的稳定标识';
COMMENT ON COLUMN "auth_credentials"."password_hash" IS '密码哈希值';
COMMENT ON COLUMN "auth_credentials"."must_change_password" IS '是否必须在下次登录后修改密码';
COMMENT ON COLUMN "auth_credentials"."password_changed_at" IS '最近一次修改密码时间';
COMMENT ON COLUMN "auth_credentials"."created_at" IS '凭据创建时间';
COMMENT ON COLUMN "auth_credentials"."updated_at" IS '凭据最近更新时间';

COMMENT ON TABLE "auth_refresh_sessions" IS '认证刷新令牌会话表（认证模块）';
COMMENT ON COLUMN "auth_refresh_sessions"."id" IS '认证会话主键';
COMMENT ON COLUMN "auth_refresh_sessions"."user_id" IS '关联用户资料的稳定标识';
COMMENT ON COLUMN "auth_refresh_sessions"."token_id" IS '刷新令牌唯一标识';
COMMENT ON COLUMN "auth_refresh_sessions"."expires_at" IS '刷新令牌失效时间';
COMMENT ON COLUMN "auth_refresh_sessions"."revoked_at" IS '会话撤销时间，为空表示仍有效';
COMMENT ON COLUMN "auth_refresh_sessions"."replaced_by_token_id" IS '令牌轮换后替代当前会话的新令牌标识';
COMMENT ON COLUMN "auth_refresh_sessions"."created_at" IS '会话创建时间';
COMMENT ON COLUMN "auth_refresh_sessions"."updated_at" IS '会话最近更新时间';
